using namespace std;

class Solution {
public:
    int minimumJumps(vector<int>& forbidden, int a, int b, int x) {
        unordered_set<int> forb(forbidden.begin(), forbidden.end());
        int max_forb = 0;
        for (int v : forbidden) max_forb = max(max_forb, v);
        int limit = max(x, max_forb) + a + b + 2000;
        queue<vector<int>> q;
        q.push({0, 0, 0}); // pos, steps, just_backed
        vector<vector<bool>> visited(limit + 1, vector<bool>(2, false));
        visited[0][0] = true;
        while (!q.empty()) {
            auto curr = q.front(); q.pop();
            int pos = curr[0], steps = curr[1], just_backed = curr[2];
            if (pos == x) return steps;
            int next_f = pos + a;
            if (next_f <= limit && forb.find(next_f) == forb.end() && !visited[next_f][0]) {
                visited[next_f][0] = true;
                q.push({next_f, steps + 1, 0});
            }
            if (!just_backed) {
                int next_b = pos - b;
                if (next_b >= 0 && forb.find(next_b) == forb.end() && !visited[next_b][1]) {
                    visited[next_b][1] = true;
                    q.push({next_b, steps + 1, 1});
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        Set<Integer> forb = new HashSet<>();
        int maxForb = 0;
        for (int v : forbidden) {
            forb.add(v);
            maxForb = Math.max(maxForb, v);
        }
        int limit = Math.max(x, maxForb) + a + b + 2000;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, 0, 0});
        boolean[][] visited = new boolean[limit + 1][2];
        visited[0][0] = true;
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int pos = curr[0], steps = curr[1], justBacked = curr[2];
            if (pos == x) return steps;
            int nextF = pos + a;
            if (nextF <= limit && !forb.contains(nextF) && !visited[nextF][0]) {
                visited[nextF][0] = true;
                q.offer(new int[]{nextF, steps + 1, 0});
            }
            if (justBacked == 0) {
                int nextB = pos - b;
                if (nextB >= 0 && !forb.contains(nextB) && !visited[nextB][1]) {
                    visited[nextB][1] = true;
                    q.offer(new int[]{nextB, steps + 1, 1});
                }
            }
        }
        return -1;
    }
}

/**
 * @param {number[]} forbidden
 * @param {number} a
 * @param {number} b
 * @param {number} x
 * @return {number}
 */
var minimumJumps = function(forbidden, a, b, x) {
    const forb = new Set(forbidden);
    let maxForb = 0;
    for (const v of forbidden) {
        if (v > maxForb) maxForb = v;
    }
    const limit = Math.max(x, maxForb) + a + b + 2000;
    const q = [[0, 0, 0]];
    const visited = new Set(['0,0']);
    while (q.length > 0) {
        const [pos, steps, justBacked] = q.shift();
        if (pos === x) return steps;
        const nextF = pos + a;
        if (nextF <= limit && !forb.has(nextF) && !visited.has(`${nextF},0`)) {
            visited.add(`${nextF},0`);
            q.push([nextF, steps + 1, 0]);
        }
        if (justBacked === 0) {
            const nextB = pos - b;
            if (nextB >= 0 && !forb.has(nextB) && !visited.has(`${nextB},1`)) {
                visited.add(`${nextB},1`);
                q.push([nextB, steps + 1, 1]);
            }
        }
    }
    return -1;
};
